94	struct Node {\n    int data;\n    Node* next;\n};\n\nclass LinkedListWrapper {\nprivate:\n    Node* head;\npublic:\n    LinkedListWrapper() : head(nullptr) {}\n    void append(int val) {}\n    int getHeadVal() const { return -1; }\n};	[{"input": "append(10), getHeadVal()", "weight": 0.3, "category": "SANITY", "expected_output": "10"}, {"input": "getHeadVal()", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "-1"}, {"input": "append(5), append(20), getHeadVal()", "weight": 0.3, "category": "EDGE", "expected_output": "5"}]	\N	2	128000	CUSTOM	\n    LinkedListWrapper()	54	struct Node {\n    int data;\n    Node* next;\n};\n\nclass LinkedListWrapper {\nprivate:\n    Node* head;\npublic:\n    LinkedListWrapper() : head(nullptr) {}\n    void append(int val) {\n        Node* newNode = new Node{val, nullptr};\n        if (head == nullptr) {\n            head = newNode;\n            return;\n        }\n        Node* curr = head;\n        while (curr->next != nullptr) {\n            curr = curr->next;\n        }\n        curr->next = newNode;\n    }\n    int getHeadVal() const {\n        if (head == nullptr) return -1;\n        return head->data;\n    }\n};	\N
106	#include <vector>\n#include <unordered_set>\n\nbool containsElement(const std::vector<int>& vec, int target) {\n    return false;\n}	[{"input": "[1, 3, 5, 7], 5", "weight": 0.3, "category": "SANITY", "is_canary": true, "is_public": false, "expected_output": "true"}, {"input": "[1, 2, 3], 10", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "false"}, {"input": "[], 1", "weight": 0.3, "category": "EDGE", "expected_output": "false"}]	\N	2	128000	SCALAR	bool containsElement(const std::vector<int>& vec, int target)	54	#include <vector>\n#include <unordered_set>\n\nbool containsElement(const std::vector<int>& vec, int target) {\n    std::unordered_set<int> s(vec.begin(), vec.end());\n    return s.find(target) != s.end();\n}	\N
38	#include <vector>\n\nvoid accumulateGridStats(const std::vector<std::vector<int>>& grid, int& totalSum, int& maxVal) {\n}	[{"input": "[[1, 5], [3, 2]], 0, 0", "weight": 0.3, "category": "SANITY", "expected_output": "[[1, 5], [3, 2]] 11 5"}, {"input": "[[-1, -5]], 0, 0", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "[[-1, -5]] -6 -1"}, {"input": "[], 0, 0", "weight": 0.3, "category": "EDGE", "expected_output": "[] 0 0"}]	\N	2	128000	CUSTOM	void accumulateGridStats(const std::vector<std::vector<int>>& grid, int& totalSum, int& maxVal)	54	#include <vector>\n#include <algorithm>\n\nvoid accumulateGridStats(const std::vector<std::vector<int>>& grid, int& totalSum, int& maxVal) {\n    totalSum = 0;\n    if (grid.empty() || grid[0].empty()) {\n        maxVal = 0;\n        return;\n    }\n    maxVal = grid[0][0];\n    for (const auto& row : grid) {\n        for (int val : row) {\n            totalSum += val;\n            maxVal = std::max(maxVal, val);\n        }\n    }\n}	\N
62	#include <iostream>\n\nint* createArray(int size, int initialValue) {\n    return nullptr;\n}	[{"input": "5, 7", "weight": 0.3, "category": "SANITY", "expected_output": "[7, 7, 7, 7, 7]"}, {"input": "1, 0", "weight": 0.4, "category": "FUNCTIONAL", "expected_output": "[0]"}, {"input": "0, 10", "weight": 0.3, "category": "EDGE", "expected_output": "nullptr"}]	\N	2	128000	CUSTOM	int* createArray(int size, int initialValue)	54	#include <iostream>\n\nint* createArray(int size, int initialValue) {\n    if (size <= 0) return nullptr;\n    int* arr = new int[size];\n    for (int i = 0; i < size; ++i) {\n        arr[i] = initialValue;\n    }\n    return arr;\n}	\N
