2929	4631	\N	\N	#include <iostream>\n\nint** allocateMatrix(int rows, int cols, int initialVal) {\n    if (rows <= 0 || cols <= 0) return nullptr;\n    int** matrix = new int*[rows];\n    for (int r = 0; r < rows; ++r) {\n        matrix[r] = new int[cols];\n        for (int c = 0; c < cols; ++c) {\n            matrix[r][c] = initialVal;\n        }\n    }\n    return matrix;\n}\n\nvoid freeMatrix(int** matrix, int rows) {\n    if (matrix == nullptr) return;\n    for (int r = 0; r < rows; ++r) {\n        delete[] matrix[r];\n    }\n    delete[] matrix;\n}	{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "2, 3, 9", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "[[9, 9, 9], [9, 9, 9]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "1, 1, 0", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "[[0]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "0, 0, 0", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "nullptr", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	0.00	2026-07-23 10:35:41.738911+00	t	\N
