10284	14027	\N	\N	struct Node {\n    int data;\n    Node* prev;\n    Node* next;\n};\n\nclass DoublyLinkedList {\nprivate:\n    Node* head;\n    Node* tail;\npublic:\n    DoublyLinkedList() : head(nullptr), tail(nullptr) {}\n    ~DoublyLinkedList() {\n        Node* curr = head;\n        while (curr != nullptr) {\n            Node* nextNode = curr->next;\n            delete curr;\n            curr = nextNode;\n        }\n    }\n    void pushFront(int val) {\n        Node* newNode = new Node{val, nullptr, head};\n        if (head != nullptr) head->prev = newNode;\n        head = newNode;\n        if (tail == nullptr) tail = head;\n    }\n    void pushBack(int val) {\n        Node* newNode = new Node{val, tail, nullptr};\n        if (tail != nullptr) tail->next = newNode;\n        tail = newNode;\n        if (head == nullptr) head = tail;\n    }\n    int popFront() {\n        if (head == nullptr) return -1;\n        Node* temp = head;\n        int val = temp->data;\n        head = head->next;\n        if (head != nullptr) head->prev = nullptr;\n        else tail = nullptr;\n        delete temp;\n        return val;\n    }\n    int popBack() {\n        if (tail == nullptr) return -1;\n        Node* temp = tail;\n        int val = temp->data;\n        tail = tail->prev;\n        if (tail != nullptr) tail->next = nullptr;\n        else head = nullptr;\n        delete temp;\n        return val;\n    }\n};	{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "pushFront(1), pushBack(2), popFront()", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\\n", "weight": 0.3, "expected": "pop:1, list:[2]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "popBack empty", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "[object]\\n", "weight": 0.4, "expected": "no-op/error flag", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "sing