10850	14579	\N	\N	#include <string>\n#include <unordered_map>\n#include <algorithm>\n\nint lengthOfLongestSubstring(const std::string& s) {\n    std::unordered_map<char, int> charMap;\n    int maxLen = 0;\n    int start = 0;\n    for (int end = 0; end < static_cast<int>(s.length()); ++end) {\n        if (charMap.count(s[end]) && charMap[s[end]] >= start) {\n            start = charMap[s[end]] + 1;\n        }\n        charMap[s[end]] = end;\n        maxLen = std::max(maxLen, end - start + 1);\n    }\n    return maxLen;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "\\"abcabcbb\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\\n", "weight": 0.3, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\\"bbbbb\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\\"\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-30 09:04:26.792555+00	t	\N
