10851	14580	\N	\N	#include <vector>\n#include <string>\n#include <unordered_map>\n#include <algorithm>\n\nstd::vector<std::string> sortWordsByAnagramGroup(const std::vector<std::string>& strs) {\n    std::unordered_map<std::string, std::vector<std::string>> groups;\n    for (const auto& s : strs) {\n        std::string key = s;\n        std::sort(key.begin(), key.end());\n        groups[key].push_back(s);\n    }\n    std::vector<std::string> result;\n    for (const auto& s : strs) {\n        std::string key = s;\n        std::sort(key.begin(), key.end());\n        if (groups.count(key)) {\n            for (const auto& item : groups[key]) {\n                result.push_back(item);\n            }\n            groups.erase(key);\n        }\n    }\n    return result;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[\\"eat\\", \\"tea\\", \\"tan\\", \\"ate\\", \\"nat\\", \\"bat\\"]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[\\"eat\\", \\"tea\\", \\"ate\\", \\"tan\\", \\"nat\\", \\"bat\\"]\\n", "weight": 0.3, "expected": "[\\"eat\\", \\"tea\\", \\"ate\\", \\"tan\\", \\"nat\\", \\"bat\\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[\\"a\\"]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[\\"a\\"]\\n", "weight": 0.4, "expected": "[\\"a\\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-30 09:04:41.889316+00	t	\N
