2448	3882	\N	\N	struct Node {\n    int data;\n    Node* next;\n};\n\nvoid splitListBySign(Node* source, Node*& posHead, Node*& negHead) {\n    posHead = nullptr;\n    negHead = nullptr;\n    Node* posTail = nullptr;\n    Node* negTail = nullptr;\n\n    Node* curr = source;\n    while (curr != nullptr) {\n        Node* newNode = new Node{curr->data, nullptr};\n        if (curr->data >= 0) {\n            if (!posHead) posHead = posTail = newNode;\n            else { posTail->next = newNode; posTail = newNode; }\n        } else {\n            if (!negHead) negHead = negTail = newNode;\n            else { negTail->next = newNode; negTail = newNode; }\n        }\n        curr = curr->next;\n    }\n}	{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[1, -2, 3, -4]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "pos:[1, 3], neg:[-2, -4]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[1, 2, 3]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "pos:[1, 2, 3], neg:[]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "pos:[], neg:[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 5. Penalty applied if > 15.", "actual_value": 5}]}}	0.00	2026-07-23 08:52:10.674922+00	t	\N
