10877	14606	\N	\N	#include <vector>\n\nint countConnectedRegion(std::vector<std::vector<int>>& grid, int r, int c) {\n    if (r < 0 || r >= (int)grid.size() || c < 0 || c >= (int)grid[0].size()) return 0;\n    if (grid[r][c] != 1) return 0;\n    grid[r][c] = 0;\n    return 1 + countConnectedRegion(grid, r + 1, c) +\n               countConnectedRegion(grid, r - 1, c) +\n               countConnectedRegion(grid, r, c + 1) +\n               countConnectedRegion(grid, r, c - 1);\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 1, 0], [1, 0, 0], [0, 0, 1]], 0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\\n", "weight": 0.3, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0, 0], [0, 0]], 0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\\n", "weight": 0.4, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[1]], 0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\\n", "weight": 0.3, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-30 09:05:57.189062+00	t	\N
