10884	14613	\N	\N	#include <iostream>\n#include <vector>\n\nvoid solveNQueens(int row, int n, std::vector<int>& cols, std::vector<int>& diag1, std::vector<int>& diag2, int& count) {\n    if (row == n) {\n        count++;\n        return;\n    }\n    for (int col = 0; col < n; ++col) {\n        if (cols[col] || diag1[row + col] || diag2[row - col + n - 1]) continue;\n        cols[col] = diag1[row + col] = diag2[row - col + n - 1] = 1;\n        solveNQueens(row + 1, n, cols, diag1, diag2, count);\n        cols[col] = diag1[row + col] = diag2[row - col + n - 1] = 0;\n    }\n}\n\nint main() {\n    int n;\n    if (std::cin >> n && n > 0) {\n        int count = 0;\n        std::vector<int> cols(n, 0), diag1(2 * n, 0), diag2(2 * n, 0);\n        solveNQueens(0, n, cols, diag1, diag2, count);\n        std::cout << count;\n    }\n    return 0;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "4", "passed": true, "status": "Accepted", "stderr": "", "stdout": "2", "weight": 0.3, "expected": "2", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "8", "passed": true, "status": "Accepted", "stderr": "", "stdout": "92", "weight": 0.4, "expected": "92", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "1", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1", "weight": 0.3, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}	10.00	2026-07-30 09:06:10.155872+00	t	\N
