9375	12025	\N	\N	#include <vector>\n#include <algorithm>\n\nint longestNonDecreasingRun(const std::vector<int>& nums) {\n    if (nums.empty()) return 0;\n    int maxLen = 1;\n    int currLen = 1;\n    for (size_t i = 1; i < nums.size(); ++i) {\n        if (nums[i] >= nums[i - 1]) {\n            currLen++;\n        } else {\n            maxLen = std::max(maxLen, currLen);\n            currLen = 1;\n        }\n    }\n    return std::max(maxLen, currLen);\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 2, 1, 3, 4, 5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "4\\n", "weight": 0.3, "expected": "4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[5, 4, 3, 2, 1]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 08:59:28.982916+00	t	\N
9356	12006	\N	\N	#include <vector>\n\nstd::vector<std::vector<int>> checkQuadrantSigns(const std::vector<std::vector<int>>& grid) {\n    std::vector<std::vector<int>> res;\n    for (const auto& point : grid) {\n        if (point.size() < 2) continue;\n        int x = point[0];\n        int y = point[1];\n        int q = 0;\n        \n        if (x > 0 && y > 0) q = 1;\n        else if (x < 0 && y > 0) q = 2;\n        else if (x < 0 && y < 0) q = 3;\n        else if (x > 0 && y < 0) q = 4;\n        else q = 0;\n        \n        res.push_back({q});\n    }\n    return res;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 2], [-1, -2]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[1], [3]]\\n", "weight": 0.3, "expected": "[[1], [3]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0, 5], [3, -4]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[0], [4]]\\n", "weight": 0.4, "expected": "[[0], [4]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[-2, 5], [0, 0]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[2], [0]]\\n", "weight": 0.3, "expected": "[[2], [0]]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 08:58:58.958914+00	t	\N
