10125	13848	\N	\N	#include <iostream>\n#include <string>\n#include <vector>\n#include <unordered_map>\n\nint main() {\n    std::vector<std::unordered_map<std::string, int>> scopes;\n    scopes.push_back({}); // global scope\n    \n    std::string cmd;\n    while (std::cin >> cmd) {\n        if (cmd == "PUSH") {\n            scopes.push_back({});\n        } else if (cmd == "POP") {\n            if (scopes.size() > 1) {\n                scopes.pop_back();\n            }\n        } else if (cmd == "SET") {\n            std::string var;\n            int val;\n            std::cin >> var >> val;\n            scopes.back()[var] = val;\n        } else if (cmd == "GET") {\n            std::string var;\n            std::cin >> var;\n            bool found = false;\n            for (int i = static_cast<int>(scopes.size()) - 1; i >= 0; --i) {\n                if (scopes[i].count(var)) {\n                    std::cout << scopes[i][var] << "\\n";\n                    found = true;\n                    break;\n                }\n            }\n            if (!found) {\n                std::cout << "UNDEFINED\\n";\n            }\n        }\n    }\n    return 0;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "SET x 10\\nPUSH\\nSET x 20\\nGET x\\nPOP\\nGET x", "passed": true, "status": "Accepted", "stderr": "", "stdout": "20\\n10\\n", "weight": 0.3, "expected": "20\\n10", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "GET y", "passed": true, "status": "Accepted", "stderr": "", "stdout": "UNDEFINED\\n", "weight": 0.4, "expected": "UNDEFINED", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "PUSH\\nPOP\\nGET z", "passed": true, "status": "Accepted", "stderr": "", "stdout": "UNDEFINED\\n", "weight": 0.3, "expected": "UNDEFINED", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "