10131	13854	\N	\N	#include <string>\n\nint calculateCompressedLength(const std::string& s) {\n    if (s.empty()) return 0;\n    int compressedLength = 0;\n    int count = 1;\n    for (size_t i = 1; i < s.length(); ++i) {\n        if (s[i] == s[i - 1]) {\n            count++;\n        } else {\n            compressedLength += 1 + std::to_string(count).length();\n            count = 1;\n        }\n    }\n    compressedLength += 1 + std::to_string(count).length();\n    return compressedLength;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "\\"aaabbc\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "6\\n", "weight": 0.3, "expected": "6", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\\"a\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "2\\n", "weight": 0.4, "expected": "2", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\\"\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 11:31:33.425064+00	t	\N
10132	13855	\N	\N	#include <string>\n#include <sstream>\n#include <algorithm>\n\nstd::string reverseWords(const std::string& sentence) {\n    if (sentence.empty()) return "";\n    std::stringstream ss(sentence);\n    std::string word;\n    std::string result = "";\n    bool first = true;\n    while (ss >> word) {\n        std::reverse(word.begin(), word.end());\n        if (!first) result += " ";\n        result += word;\n        first = false;\n    }\n    return result;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "\\"Hello World\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\\"olleH dlroW\\"\\n", "weight": 0.3, "expected": "\\"olleH dlroW\\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\\"a b c\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\\"a b c\\"\\n", "weight": 0.4, "expected": "\\"a b c\\"", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\\"\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "\\"\\"\\n", "weight": 0.3, "expected": "\\"\\"", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 11:31:37.047978+00	t	\N
10133	13856	\N	\N	#include <vector>\n#include <string>\n\nstd::vector<std::string> transposeCharGrid(const std::vector<std::string>& grid) {\n    if (grid.empty() || grid[0].empty()) return {};\n    size_t rows = grid.size();\n    size_t cols = grid[0].length();\n    std::vector<std::string> transposed(cols, std::string(rows, ' '));\n    for (size_t r = 0; r < rows; ++r) {\n        for (size_t c = 0; c < cols; ++c) {\n            transposed[c][r] = grid[r][c];\n        }\n    }\n    return transposed;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[\\"abc\\", \\"def\\"]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[\\"ad\\", \\"be\\", \\"cf\\"]\\n", "weight": 0.3, "expected": "[\\"ad\\", \\"be\\", \\"cf\\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[\\"x\\"]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[\\"x\\"]\\n", "weight": 0.4, "expected": "[\\"x\\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 11:31:40.757046+00	t	\N
10134	13857	\N	\N	#include <string>\n#include <vector>\n#include <algorithm>\n\nstruct Node {\n    char data;\n    Node* next;\n};\n\nbool isListAnagramOf(Node* head, std::string target) {\n    std::string listStr = "";\n    Node* curr = head;\n    while (curr != nullptr) {\n        listStr += curr->data;\n        curr = curr->next;\n    }\n    if (listStr.length() != target.length()) return false;\n    std::sort(listStr.begin(), listStr.end());\n    std::sort(target.begin(), target.end());\n    return listStr == target;\n}	{"feedback": "Passed 30% of the functional test suites.", "black_box": {"ratio": 0.3, "test_results": [{"input": "['l', 'i', 's', 't'], \\"silent\\"", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: ['l', 'i', 's', 't'], \\"silent\\"\\n", "stdout": "", "weight": 0.3, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "['c', 'a', 't'], \\"act\\"", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: ['c', 'a', 't'], \\"act\\"\\n", "stdout": "", "weight": 0.4, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], \\"\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.3, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	3.00	2026-07-29 11:31:44.774013+00	t	\N
10135	13858	\N	\N	#include <iostream>\n#include <string>\n\nint main() {\n    std::string text, pattern;\n    if (std::cin >> text >> pattern) {\n        bool first = true;\n        size_t pos = text.find(pattern, 0);\n        while (pos != std::string::npos) {\n            if (!first) std::cout << " ";\n            std::cout << pos;\n            first = false;\n            pos = text.find(pattern, pos + 1);\n        }\n    }\n    return 0;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "abababa\\naba", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0 2 4", "weight": 0.3, "expected": "0 4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "hello\\nworld", "passed": true, "status": "Accepted", "stderr": "", "stdout": "", "weight": 0.4, "expected": "", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "aaaa\\naa", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0 1 2", "weight": 0.3, "expected": "0 2", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}	10.00	2026-07-29 11:31:48.599766+00	t	\N
10136	13859	\N	\N	#include <string>\n#include <unordered_map>\n#include <algorithm>\n\nint lengthOfLongestSubstring(const std::string& s) {\n    std::unordered_map<char, int> charMap;\n    int maxLen = 0;\n    int start = 0;\n    for (int end = 0; end < static_cast<int>(s.length()); ++end) {\n        if (charMap.count(s[end]) && charMap[s[end]] >= start) {\n            start = charMap[s[end]] + 1;\n        }\n        charMap[s[end]] = end;\n        maxLen = std::max(maxLen, end - start + 1);\n    }\n    return maxLen;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "\\"abcabcbb\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\\n", "weight": 0.3, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\\"bbbbb\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\\"\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 11:31:52.520852+00	t	\N
10137	13860	\N	\N	#include <vector>\n#include <string>\n#include <unordered_map>\n#include <algorithm>\n\nstd::vector<std::string> sortWordsByAnagramGroup(const std::vector<std::string>& strs) {\n    std::unordered_map<std::string, std::vector<std::string>> groups;\n    for (const auto& s : strs) {\n        std::string key = s;\n        std::sort(key.begin(), key.end());\n        groups[key].push_back(s);\n    }\n    std::vector<std::string> result;\n    for (const auto& s : strs) {\n        std::string key = s;\n        std::sort(key.begin(), key.end());\n        if (groups.count(key)) {\n            for (const auto& item : groups[key]) {\n                result.push_back(item);\n            }\n            groups.erase(key);\n        }\n    }\n    return result;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[\\"eat\\", \\"tea\\", \\"tan\\", \\"ate\\", \\"nat\\", \\"bat\\"]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[\\"eat\\", \\"tea\\", \\"ate\\", \\"tan\\", \\"nat\\", \\"bat\\"]\\n", "weight": 0.3, "expected": "[\\"eat\\", \\"tea\\", \\"ate\\", \\"tan\\", \\"nat\\", \\"bat\\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[\\"a\\"]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[\\"a\\"]\\n", "weight": 0.4, "expected": "[\\"a\\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 11:31:54.122026+00	t	\N
10138	13861	\N	\N	#include <vector>\n#include <string>\n\nbool dfs(std::vector<std::vector<char>>& board, const std::string& word, int r, int c, size_t index) {\n    if (index == word.length()) return true;\n    if (r < 0 || r >= static_cast<int>(board.size()) || c < 0 || c >= static_cast<int>(board[0].size()) || board[r][c] != word[index]) {\n        return false;\n    }\n    char temp = board[r][c];\n    board[r][c] = '#';\n    bool found = dfs(board, word, r + 1, c, index + 1) ||\n                 dfs(board, word, r - 1, c, index + 1) ||\n                 dfs(board, word, r, c + 1, index + 1) ||\n                 dfs(board, word, r, c - 1, index + 1);\n    board[r][c] = temp;\n    return found;\n}\n\nbool existWord(const std::vector<std::vector<char>>& board, std::string word) {\n    if (board.empty() || board[0].empty()) return false;\n    auto grid = board;\n    for (size_t r = 0; r < grid.size(); ++r) {\n        for (size_t c = 0; c < grid[0].size(); ++c) {\n            if (dfs(grid, word, static_cast<int>(r), static_cast<int>(c), 0)) {\n                return true;\n            }\n        }\n    }\n    return false;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[['A','B','C','E'],['S','F','C','S'],['A','D','E','E']], \\"ABCCED\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[['A','B']], \\"AC\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\\n", "weight": 0.4, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], \\"A\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\\n", "weight": 0.3, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor dire