10907	14636	\N	\N	#include <vector>\n#include <queue>\n\nint shortestPathGrid(const std::vector<std::vector<int>>& grid) {\n    if (grid.empty() || grid[0].empty()) return -1;\n    int rows = grid.size();\n    int cols = grid[0].size();\n    if (grid[0][0] != 0 || grid[rows-1][cols-1] != 0) return -1;\n    if (rows == 1 && cols == 1) return 1;\n\n    std::queue<std::pair<int, int>> q;\n    std::vector<std::vector<int>> dist(rows, std::vector<int>(cols, -1));\n\n    q.push({0, 0});\n    dist[0][0] = 1;\n\n    int dr[] = {1, -1, 0, 0};\n    int dc[] = {0, 0, 1, -1};\n\n    while (!q.empty()) {\n        auto [r, c] = q.front();\n        q.pop();\n\n        for (int i = 0; i < 4; ++i) {\n            int nr = r + dr[i];\n            int nc = c + dc[i];\n\n            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 0 && dist[nr][nc] == -1) {\n                dist[nr][nc] = dist[r][c] + 1;\n                if (nr == rows - 1 && nc == cols - 1) return dist[nr][nc];\n                q.push({nr, nc});\n            }\n        }\n    }\n    return -1;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[0,0,0],[1,1,0],[0,0,0]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "5\\n", "weight": 0.3, "expected": "5", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0,1],[1,0]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-1\\n", "weight": 0.4, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\\n", "weight": 0.3, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-30 09:06:52.406787+00	t	\N
