10910	14639	\N	\N	#include <unordered_map>\n#include <list>\n\nclass LRUCache {\nprivate:\n    int cap;\n    std::list<std::pair<int, int>> cache;\n    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> map;\npublic:\n    LRUCache(int capacity) : cap(capacity) {}\n\n    int get(int key) {\n        if (!map.count(key)) return -1;\n        cache.splice(cache.begin(), cache, map[key]);\n        return map[key]->second;\n    }\n\n    void put(int key, int value) {\n        if (map.count(key)) {\n            map[key]->second = value;\n            cache.splice(cache.begin(), cache, map[key]);\n            return;\n        }\n        if (static_cast<int>(cache.size()) == cap) {\n            int delKey = cache.back().first;\n            cache.pop_back();\n            map.erase(delKey);\n        }\n        cache.push_front({key, value});\n        map[key] = cache.begin();\n    }\n};	{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "cap=2, put(1,1), put(2,2), get(1), put(3,3), get(2)", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "get(1)=1, get(2)=-1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "get non-existent", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.4, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "put update existing key", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "updated value returned", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	0.00	2026-07-30 09:06:59.142527+00	t	\N
10911	14640	\N	\N	#include <vector>\n#include <deque>\n\nstd::vector<int> maxSlidingWindow(const std::vector<int>& nums, int k) {\n    if (nums.empty() || k <= 0) return {};\n    std::vector<int> result;\n    std::deque<int> dq;\n\n    for (int i = 0; i < static_cast<int>(nums.size()); ++i) {\n        if (!dq.empty() && dq.front() == i - k) {\n            dq.pop_front();\n        }\n        while (!dq.empty() && nums[dq.back()] <= nums[i]) {\n            dq.pop_back();\n        }\n        dq.push_back(i);\n        if (i >= k - 1) {\n            result.push_back(nums[dq.front()]);\n        }\n    }\n    return result;\n}	{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[1,3,-1,-3,5,3,6,7], k=3", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [1,3,-1,-3,5,3,6,7], k=3\\n", "stdout": "", "weight": 0.3, "expected": "[3,3,5,5,6,7]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[1], k=1", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [1], k=1\\n", "stdout": "", "weight": 0.4, "expected": "[1]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], k=0", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [], k=0\\n", "stdout": "", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	0.00	2026-07-30 09:07:02.724188+00	t	\N
10912	14641	\N	\N	#include <vector>\n#include <queue>\n#include <tuple>\n\nint minCostGridPath(const std::vector<std::vector<int>>& grid) {\n    if (grid.empty() || grid[0].empty()) return 0;\n    int rows = grid.size();\n    int cols = grid[0].size();\n\n    std::priority_queue<std::tuple<int, int, int>, std::vector<std::tuple<int, int, int>>, std::greater<std::tuple<int, int, int>>> pq;\n    std::vector<std::vector<int>> dist(rows, std::vector<int>(cols, 1e9));\n\n    dist[0][0] = grid[0][0];\n    pq.push({grid[0][0], 0, 0});\n\n    int dr[] = {1, -1, 0, 0};\n    int dc[] = {0, 0, 1, -1};\n\n    while (!pq.empty()) {\n        auto [d, r, c] = pq.top();\n        pq.pop();\n\n        if (r == rows - 1 && c == cols - 1) return d;\n        if (d > dist[r][c]) continue;\n\n        for (int i = 0; i < 4; ++i) {\n            int nr = r + dr[i];\n            int nc = c + dc[i];\n\n            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {\n                if (dist[r][c] + grid[nr][nc] < dist[nr][nc]) {\n                    dist[nr][nc] = dist[r][c] + grid[nr][nc];\n                    pq.push({dist[nr][nc], nr, nc});\n                }\n            }\n        }\n    }\n    return dist[rows - 1][cols - 1];\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1,3,1],[1,5,1],[4,2,1]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "7\\n", "weight": 0.3, "expected": "7", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[1,2],[1,1]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\\n", "weight": 0.4, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[5]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "5\\n", "weight": 0.3, "expected": "5", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-30 09:07:04.309611+00	t	\N
10913	14642	\N	\N	#include <vector>\n#include <queue>\n\nstruct Node {\n    int data;\n    Node* next;\n};\n\nstruct CompareNode {\n    bool operator()(Node* a, Node* b) {\n        return a->data > b->data;\n    }\n};\n\nNode* mergeKSortedLists(const std::vector<Node*>& lists) {\n    std::priority_queue<Node*, std::vector<Node*>, CompareNode> pq;\n    for (auto node : lists) {\n        if (node != nullptr) pq.push(node);\n    }\n    Node dummy{0, nullptr};\n    Node* tail = &dummy;\n\n    while (!pq.empty()) {\n        Node* top = pq.top();\n        pq.pop();\n        tail->next = top;\n        tail = tail->next;\n        if (top->next != nullptr) {\n            pq.push(top->next);\n        }\n    }\n    return dummy.next;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1,4,5],[1,3,4],[2,6]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[1, 1, 2, 3, 4, 4, 5, 6]\\n", "weight": 0.3, "expected": "[1,1,2,3,4,4,5,6]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\\n", "weight": 0.4, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-30 09:07:05.899088+00	t	\N
10914	14643	\N	\N	#include <iostream>\n#include <queue>\n#include <iomanip>\n\nint main() {\n    int n;\n    if (std::cin >> n && n > 0) {\n        std::priority_queue<int> maxHeap;\n        std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap;\n\n        for (int i = 0; i < n; ++i) {\n            int val;\n            std::cin >> val;\n            if (maxHeap.empty() || val <= maxHeap.top()) {\n                maxHeap.push(val);\n            } else {\n                minHeap.push(val);\n            }\n\n            if (maxHeap.size() > minHeap.size() + 1) {\n                minHeap.push(maxHeap.top());\n                maxHeap.pop();\n            } else if (minHeap.size() > maxHeap.size()) {\n                maxHeap.push(minHeap.top());\n                minHeap.pop();\n            }\n\n            if (maxHeap.size() == minHeap.size()) {\n                double med = (maxHeap.top() + minHeap.top()) / 2.0;\n                std::cout << std::fixed << std::setprecision(1) << med << "\\n";\n            } else {\n                std::cout << std::fixed << std::setprecision(1) << static_cast<double>(maxHeap.top()) << "\\n";\n            }\n        }\n    }\n    return 0;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "3\\n1\\n2\\n3", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1.0\\n1.5\\n2.0\\n", "weight": 0.3, "expected": "1.0\\n1.5\\n2.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "1\\n5", "passed": true, "status": "Accepted", "stderr": "", "stdout": "5.0\\n", "weight": 0.4, "expected": "5.0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "2\\n10 20", "passed": true, "status": "Accepted", "stderr": "", "stdout": "10.0\\n15.0\\n", "weight": 0.3, "expected": "10.0\\n15.0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "D