11176	15076	\N	\N	#include <iostream>\n\nint* flattenRawMatrix(int** matrix, int rows, int cols) {\n    if (matrix == nullptr || rows <= 0 || cols <= 0) return nullptr;\n    int* flat = new int[rows * cols];\n    int idx = 0;\n    for (int r = 0; r < rows; ++r) {\n        if (matrix[r] == nullptr) continue;\n        for (int c = 0; c < cols; ++c) {\n            flat[idx++] = matrix[r][c];\n        }\n    }\n    return flat;\n}	{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[[1, 2], [3, 4]], 2, 2", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [[1, 2], [3, 4]], 2, 2\\n", "stdout": "", "weight": 0.3, "expected": "[1, 2, 3, 4]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[5]], 1, 1", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [[5]], 1, 1\\n", "stdout": "", "weight": 0.4, "expected": "[5]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "nullptr, 0, 0", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: nullptr, 0, 0\\n", "stdout": "", "weight": 0.3, "expected": "nullptr", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	0.00	2026-07-30 09:28:48.936658+00	t	\N
10972	14701	\N	\N	#include <vector>\n#include <string>\n\nbool dfs(std::vector<std::vector<char>>& board, const std::string& word, int r, int c, size_t index) {\n    if (index == word.length()) return true;\n    if (r < 0 || r >= static_cast<int>(board.size()) || c < 0 || c >= static_cast<int>(board[0].size()) || board[r][c] != word[index]) {\n        return false;\n    }\n    char temp = board[r][c];\n    board[r][c] = '#';\n    bool found = dfs(board, word, r + 1, c, index + 1) ||\n                 dfs(board, word, r - 1, c, index + 1) ||\n                 dfs(board, word, r, c + 1, index + 1) ||\n                 dfs(board, word, r, c - 1, index + 1);\n    board[r][c] = temp;\n    return found;\n}\n\nbool existWord(const std::vector<std::vector<char>>& board, std::string word) {\n    if (board.empty() || board[0].empty()) return false;\n    auto grid = board;\n    for (size_t r = 0; r < grid.size(); ++r) {\n        for (size_t c = 0; c < grid[0].size(); ++c) {\n            if (dfs(grid, word, static_cast<int>(r), static_cast<int>(c), 0)) {\n                return true;\n            }\n        }\n    }\n    return false;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[['A','B','C','E'],['S','F','C','S'],['A','D','E','E']], \\"ABCCED\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[['A','B']], \\"AC\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\\n", "weight": 0.4, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], \\"A\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\\n", "weight": 0.3, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-30 09:08:44.19267+00	t	\N
10973	14702	\N	\N	#include <vector>\n\nstruct Node {\n    char data;\n    Node* next;\n};\n\nbool isPalindromeList(Node* head) {\n    std::vector<char> chars;\n    Node* curr = head;\n    while (curr != nullptr) {\n        chars.push_back(curr->data);\n        curr = curr->next;\n    }\n    int left = 0;\n    int right = static_cast<int>(chars.size()) - 1;\n    while (left < right) {\n        if (chars[left] != chars[right]) return false;\n        left++;\n        right--;\n    }\n    return true;\n}	{"feedback": "Passed 30% of the functional test suites.", "black_box": {"ratio": 0.3, "test_results": [{"input": "['r', 'a', 'c', 'e', 'c', 'a', 'r']", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: ['r', 'a', 'c', 'e', 'c', 'a', 'r']\\n", "stdout": "", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "['a', 'b']", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: ['a', 'b']\\n", "stdout": "", "weight": 0.4, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.3, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	3.00	2026-07-30 09:08:45.745509+00	t	\N
10974	14703	\N	\N	#include <iostream>\n#include <string>\n#include <stack>\n#include <cctype>\n\nint main() {\n    std::string s;\n    if (std::getline(std::cin, s)) {\n        std::stack<int> st;\n        int num = 0;\n        char op = '+';\n        for (size_t i = 0; i < s.length(); ++i) {\n            char c = s[i];\n            if (std::isdigit(c)) {\n                num = num * 10 + (c - '0');\n            }\n            if ((!std::isdigit(c) && !std::isspace(c)) || i == s.length() - 1) {\n                if (op == '+') st.push(num);\n                else if (op == '-') st.push(-num);\n                else if (op == '*') {\n                    int top = st.top(); st.pop();\n                    st.push(top * num);\n                } else if (op == '/') {\n                    int top = st.top(); st.pop();\n                    st.push(top / num);\n                }\n                op = c;\n                num = 0;\n            }\n        }\n        int result = 0;\n        while (!st.empty()) {\n            result += st.top();\n            st.pop();\n        }\n        std::cout << result;\n    }\n    return 0;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "3+2*2", "passed": true, "status": "Accepted", "stderr": "", "stdout": "7", "weight": 0.3, "expected": "7", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": " 3/2 ", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": " 3+5 / 2 ", "passed": true, "status": "Accepted", "stderr": "", "stdout": "5", "weight": 0.3, "expected": "5", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}	10.00	2026-07-30 09:08:47.30807+00	t	\N
