10981	14710	\N	\N	#include <iostream>\n\nint* filterEvenNumbers(const int* arr, int size, int& newSize) {\n    if (arr == nullptr || size <= 0) {\n        newSize = 0;\n        return nullptr;\n    }\n    int count = 0;\n    for (int i = 0; i < size; ++i) {\n        if (arr[i] % 2 == 0) count++;\n    }\n    newSize = count;\n    if (count == 0) return nullptr;\n\n    int* result = new int[count];\n    int idx = 0;\n    for (int i = 0; i < size; ++i) {\n        if (arr[i] % 2 == 0) {\n            result[idx++] = arr[i];\n        }\n    }\n    return result;\n}	{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "[1, 2, 3, 4, 5], 5", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [1, 2, 3, 4, 5], 5\\n", "stdout": "", "weight": 0.3, "expected": "[2, 4], size=2", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[1, 3, 5], 3", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: [1, 3, 5], 3\\n", "stdout": "", "weight": 0.4, "expected": "nullptr, size=0", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "nullptr, 0", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: nullptr, 0\\n", "stdout": "", "weight": 0.3, "expected": "nullptr, size=0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	0.00	2026-07-30 09:08:58.317262+00	t	\N
