9451	12267	\N	\N	struct Node {\n    int data;\n    Node* next;\n};\n\nint getMiddleNodeData(Node* head) {\n    if (head == nullptr) return -1;\n    Node* slow = head;\n    Node* fast = head;\n    while (fast != nullptr && fast->next != nullptr) {\n        slow = slow->next;\n        fast = fast->next->next;\n    }\n    return slow->data;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 3, 4, 5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\\n", "weight": 0.3, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[1, 2, 3, 4]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\\n", "weight": 0.4, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-1\\n", "weight": 0.3, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 4. Penalty applied if > 15.", "actual_value": 4}]}}	10.00	2026-07-29 09:44:37.007173+00	t	\N
9435	12251	\N	\N	#include <vector>\n\nstd::vector<std::vector<int>> checkBoundaryStatus(const std::vector<std::vector<int>>& grid) {\n    std::vector<std::vector<int>> res = grid;\n    int rows = res.size();\n    if (rows == 0) return res;\n    int cols = res[0].size();\n    for (int r = 0; r < rows; ++r) {\n        for (int c = 0; c < cols; ++c) {\n            bool isBoundary = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);\n            if (!isBoundary) {\n                if (res[r][c] == 5) res[r][c] = -1;\n                else res[r][c] = -2;\n            }\n        }\n    }\n    return res;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 2, 3], [4, 5, 6], [7, 8, 9]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[1, 2, 3], [4, -1, 6], [7, 8, 9]]\\n", "weight": 0.3, "expected": "[[1, 2, 3], [4, -1, 6], [7, 8, 9]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[1, 1], [1, 1]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[1, 1], [1, 1]]\\n", "weight": 0.4, "expected": "[[1, 1], [1, 1]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[5, 5, 5], [5, -3, 5], [5, 5, 5]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[5, 5, 5], [5, -2, 5], [5, 5, 5]]\\n", "weight": 0.3, "expected": "[[5, 5, 5], [5, -2, 5], [5, 5, 5]]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 09:44:05.446062+00	t	\N
9455	12271	\N	\N	#include <vector>\n\nstd::vector<int> spiralTraversal(const std::vector<std::vector<int>>& matrix) {\n    if (matrix.empty() || matrix[0].empty()) return {};\n    int top = 0, bottom = matrix.size() - 1;\n    int left = 0, right = matrix[0].size() - 1;\n    std::vector<int> result;\n\n    while (top <= bottom && left <= right) {\n        for (int c = left; c <= right; ++c) result.push_back(matrix[top][c]);\n        top++;\n        for (int r = top; r <= bottom; ++r) result.push_back(matrix[r][right]);\n        right--;\n\n        if (top <= bottom) {\n            for (int c = right; c >= left; --c) result.push_back(matrix[bottom][c]);\n            bottom--;\n        }\n        if (left <= right) {\n            for (int r = bottom; r >= top; --r) result.push_back(matrix[r][left]);\n            left++;\n        }\n    }\n    return result;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 2, 3], [4, 5, 6], [7, 8, 9]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[1, 2, 3, 6, 9, 8, 7, 4, 5]\\n", "weight": 0.3, "expected": "[1, 2, 3, 6, 9, 8, 7, 4, 5]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[1]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[1]\\n", "weight": 0.4, "expected": "[1]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 09:44:43.248721+00	t	\N
