9450	12266	\N	\N	#include <vector>                                                                      \n                                                                                                     \nstd::vector<int> computeRowAlternatingSums(const std::vector<std::vector<int>>& grid) {\n  std::vector<int> res;                                                              \n  for (size_t r = 0; r < grid.size(); ++r) {                                         \n    int sum = 0;                                                                   \n    for (size_t c = 0; c < grid[r].size(); ++c) {                                  \n      if (c % 2 == 0){\n        sum += grid[r][c];\n      }\n      else {\t\t\t\t\t\t\t\t      \n        sum -= grid[r][c]; \t\t\t\t\t\t      \n      }                                         \t\t\t\t      \n    }                                                                             \n    res.push_back(sum);                                                            \n  }                                                                                  \n  return res;                                                                        \n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 2, 3], [4, 5, 6]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[2, 5]\\n", "weight": 0.5, "expected": "[2, 5]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[10]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[10]\\n", "weight": 0.5, "expected": "[10]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 09:44:35.455488+00	t	\N
9449	12265	\N	\N	#include <vector>\n#include <algorithm>\n\nint longestNonDecreasingRun(const std::vector<int>& nums) {\n    if (nums.empty()) return 0;\n    int maxLen = 1;\n    int currLen = 1;\n    for (size_t i = 1; i < nums.size(); ++i) {\n        if (nums[i] >= nums[i - 1]) {\n            currLen++;\n        } else {\n            maxLen = std::max(maxLen, currLen);\n            currLen = 1;\n        }\n    }\n    return std::max(maxLen, currLen);\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 2, 1, 3, 4, 5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "4\\n", "weight": 0.3, "expected": "4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[5, 4, 3, 2, 1]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 09:44:33.900939+00	t	\N
