9609	12776	\N	\N	#include <vector>\n#include <string>\n\nstd::vector<std::string> transposeCharGrid(const std::vector<std::string>& grid) {\n    if (grid.empty() || grid[0].empty()) return {};\n    size_t rows = grid.size();\n    size_t cols = grid[0].length();\n    std::vector<std::string> transposed(cols, std::string(rows, ' '));\n    for (size_t r = 0; r < rows; ++r) {\n        for (size_t c = 0; c < cols; ++c) {\n            transposed[c][r] = grid[r][c];\n        }\n    }\n    return transposed;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[\\"abc\\", \\"def\\"]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[\\"ad\\", \\"be\\", \\"cf\\"]\\n", "weight": 0.3, "expected": "[\\"ad\\", \\"be\\", \\"cf\\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[\\"x\\"]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[\\"x\\"]\\n", "weight": 0.4, "expected": "[\\"x\\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 10:13:10.718948+00	t	\N
9610	12777	\N	\N	#include <string>\n#include <vector>\n#include <algorithm>\n\nstruct Node {\n    char data;\n    Node* next;\n};\n\nbool isListAnagramOf(Node* head, std::string target) {\n    std::string listStr = "";\n    Node* curr = head;\n    while (curr != nullptr) {\n        listStr += curr->data;\n        curr = curr->next;\n    }\n    if (listStr.length() != target.length()) return false;\n    std::sort(listStr.begin(), listStr.end());\n    std::sort(target.begin(), target.end());\n    return listStr == target;\n}	{"feedback": "Passed 30% of the functional test suites.", "black_box": {"ratio": 0.3, "test_results": [{"input": "['l', 'i', 's', 't'], \\"silent\\"", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: ['l', 'i', 's', 't'], \\"silent\\"\\n", "stdout": "", "weight": 0.3, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "['c', 'a', 't'], \\"act\\"", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: ['c', 'a', 't'], \\"act\\"\\n", "stdout": "", "weight": 0.4, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], \\"\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.3, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	3.00	2026-07-29 10:13:12.279091+00	t	\N
