9612	12779	\N	\N	#include <string>\n#include <unordered_map>\n#include <algorithm>\n\nint lengthOfLongestSubstring(const std::string& s) {\n    std::unordered_map<char, int> charMap;\n    int maxLen = 0;\n    int start = 0;\n    for (int end = 0; end < static_cast<int>(s.length()); ++end) {\n        if (charMap.count(s[end]) && charMap[s[end]] >= start) {\n            start = charMap[s[end]] + 1;\n        }\n        charMap[s[end]] = end;\n        maxLen = std::max(maxLen, end - start + 1);\n    }\n    return maxLen;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "\\"abcabcbb\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\\n", "weight": 0.3, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\\"bbbbb\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\\"\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 10:13:15.434908+00	t	\N
9613	12780	\N	\N	#include <vector>\n#include <string>\n#include <unordered_map>\n#include <algorithm>\n\nstd::vector<std::string> sortWordsByAnagramGroup(const std::vector<std::string>& strs) {\n    std::unordered_map<std::string, std::vector<std::string>> groups;\n    for (const auto& s : strs) {\n        std::string key = s;\n        std::sort(key.begin(), key.end());\n        groups[key].push_back(s);\n    }\n    std::vector<std::string> result;\n    for (const auto& s : strs) {\n        std::string key = s;\n        std::sort(key.begin(), key.end());\n        if (groups.count(key)) {\n            for (const auto& item : groups[key]) {\n                result.push_back(item);\n            }\n            groups.erase(key);\n        }\n    }\n    return result;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[\\"eat\\", \\"tea\\", \\"tan\\", \\"ate\\", \\"nat\\", \\"bat\\"]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[\\"eat\\", \\"tea\\", \\"ate\\", \\"tan\\", \\"nat\\", \\"bat\\"]\\n", "weight": 0.3, "expected": "[\\"eat\\", \\"tea\\", \\"ate\\", \\"tan\\", \\"nat\\", \\"bat\\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[\\"a\\"]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[\\"a\\"]\\n", "weight": 0.4, "expected": "[\\"a\\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 10:13:17.010013+00	t	\N
9614	12781	\N	\N	#include <vector>\n#include <string>\n\nbool dfs(std::vector<std::vector<char>>& board, const std::string& word, int r, int c, size_t index) {\n    if (index == word.length()) return true;\n    if (r < 0 || r >= static_cast<int>(board.size()) || c < 0 || c >= static_cast<int>(board[0].size()) || board[r][c] != word[index]) {\n        return false;\n    }\n    char temp = board[r][c];\n    board[r][c] = '#';\n    bool found = dfs(board, word, r + 1, c, index + 1) ||\n                 dfs(board, word, r - 1, c, index + 1) ||\n                 dfs(board, word, r, c + 1, index + 1) ||\n                 dfs(board, word, r, c - 1, index + 1);\n    board[r][c] = temp;\n    return found;\n}\n\nbool existWord(const std::vector<std::vector<char>>& board, std::string word) {\n    if (board.empty() || board[0].empty()) return false;\n    auto grid = board;\n    for (size_t r = 0; r < grid.size(); ++r) {\n        for (size_t c = 0; c < grid[0].size(); ++c) {\n            if (dfs(grid, word, static_cast<int>(r), static_cast<int>(c), 0)) {\n                return true;\n            }\n        }\n    }\n    return false;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[['A','B','C','E'],['S','F','C','S'],['A','D','E','E']], \\"ABCCED\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[['A','B']], \\"AC\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\\n", "weight": 0.4, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], \\"A\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\\n", "weight": 0.3, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 10:13:20.61638+00	t	\N
9615	12782	\N	\N	#include <vector>\n\nstruct Node {\n    char data;\n    Node* next;\n};\n\nbool isPalindromeList(Node* head) {\n    std::vector<char> chars;\n    Node* curr = head;\n    while (curr != nullptr) {\n        chars.push_back(curr->data);\n        curr = curr->next;\n    }\n    int left = 0;\n    int right = static_cast<int>(chars.size()) - 1;\n    while (left < right) {\n        if (chars[left] != chars[right]) return false;\n        left++;\n        right--;\n    }\n    return true;\n}	{"feedback": "Passed 30% of the functional test suites.", "black_box": {"ratio": 0.3, "test_results": [{"input": "['r', 'a', 'c', 'e', 'c', 'a', 'r']", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: ['r', 'a', 'c', 'e', 'c', 'a', 'r']\\n", "stdout": "", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "['a', 'b']", "passed": false, "status": "Wrong Answer", "stderr": "PARSE_ERROR: input line did not match expected parameter types for this signature: ['a', 'b']\\n", "stdout": "", "weight": 0.4, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 0.3, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	3.00	2026-07-29 10:13:22.208305+00	t	\N
9616	12783	\N	\N	#include <iostream>\n#include <string>\n#include <stack>\n#include <cctype>\n\nint main() {\n    std::string s;\n    if (std::getline(std::cin, s)) {\n        std::stack<int> st;\n        int num = 0;\n        char op = '+';\n        for (size_t i = 0; i < s.length(); ++i) {\n            char c = s[i];\n            if (std::isdigit(c)) {\n                num = num * 10 + (c - '0');\n            }\n            if ((!std::isdigit(c) && !std::isspace(c)) || i == s.length() - 1) {\n                if (op == '+') st.push(num);\n                else if (op == '-') st.push(-num);\n                else if (op == '*') {\n                    int top = st.top(); st.pop();\n                    st.push(top * num);\n                } else if (op == '/') {\n                    int top = st.top(); st.pop();\n                    st.push(top / num);\n                }\n                op = c;\n                num = 0;\n            }\n        }\n        int result = 0;\n        while (!st.empty()) {\n            result += st.top();\n            st.pop();\n        }\n        std::cout << result;\n    }\n    return 0;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "3+2*2", "passed": true, "status": "Accepted", "stderr": "", "stdout": "7", "weight": 0.3, "expected": "7", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": " 3/2 ", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": " 3+5 / 2 ", "passed": true, "status": "Accepted", "stderr": "", "stdout": "5", "weight": 0.3, "expected": "5", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}	10.00	2026-07-29 10:13:25.809069+00	t	\N
