9705	13019	\N	\N	#include <string>\n#include <unordered_map>\n#include <algorithm>\n\nint lengthOfLongestSubstring(const std::string& s) {\n    std::unordered_map<char, int> charMap;\n    int maxLen = 0;\n    int start = 0;\n    for (int end = 0; end < static_cast<int>(s.length()); ++end) {\n        if (charMap.count(s[end]) && charMap[s[end]] >= start) {\n            start = charMap[s[end]] + 1;\n        }\n        charMap[s[end]] = end;\n        maxLen = std::max(maxLen, end - start + 1);\n    }\n    return maxLen;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "\\"abcabcbb\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\\n", "weight": 0.3, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\\"bbbbb\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\\"\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 10:24:13.356016+00	t	\N
9706	13020	\N	\N	#include <vector>\n#include <string>\n#include <unordered_map>\n#include <algorithm>\n\nstd::vector<std::string> sortWordsByAnagramGroup(const std::vector<std::string>& strs) {\n    std::unordered_map<std::string, std::vector<std::string>> groups;\n    for (const auto& s : strs) {\n        std::string key = s;\n        std::sort(key.begin(), key.end());\n        groups[key].push_back(s);\n    }\n    std::vector<std::string> result;\n    for (const auto& s : strs) {\n        std::string key = s;\n        std::sort(key.begin(), key.end());\n        if (groups.count(key)) {\n            for (const auto& item : groups[key]) {\n                result.push_back(item);\n            }\n            groups.erase(key);\n        }\n    }\n    return result;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[\\"eat\\", \\"tea\\", \\"tan\\", \\"ate\\", \\"nat\\", \\"bat\\"]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[\\"eat\\", \\"tea\\", \\"ate\\", \\"tan\\", \\"nat\\", \\"bat\\"]\\n", "weight": 0.3, "expected": "[\\"eat\\", \\"tea\\", \\"ate\\", \\"tan\\", \\"nat\\", \\"bat\\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[\\"a\\"]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[\\"a\\"]\\n", "weight": 0.4, "expected": "[\\"a\\"]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 10:24:14.941486+00	t	\N
9707	13021	\N	\N	#include <vector>\n#include <string>\n\nbool dfs(std::vector<std::vector<char>>& board, const std::string& word, int r, int c, size_t index) {\n    if (index == word.length()) return true;\n    if (r < 0 || r >= static_cast<int>(board.size()) || c < 0 || c >= static_cast<int>(board[0].size()) || board[r][c] != word[index]) {\n        return false;\n    }\n    char temp = board[r][c];\n    board[r][c] = '#';\n    bool found = dfs(board, word, r + 1, c, index + 1) ||\n                 dfs(board, word, r - 1, c, index + 1) ||\n                 dfs(board, word, r, c + 1, index + 1) ||\n                 dfs(board, word, r, c - 1, index + 1);\n    board[r][c] = temp;\n    return found;\n}\n\nbool existWord(const std::vector<std::vector<char>>& board, std::string word) {\n    if (board.empty() || board[0].empty()) return false;\n    auto grid = board;\n    for (size_t r = 0; r < grid.size(); ++r) {\n        for (size_t c = 0; c < grid[0].size(); ++c) {\n            if (dfs(grid, word, static_cast<int>(r), static_cast<int>(c), 0)) {\n                return true;\n            }\n        }\n    }\n    return false;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[['A','B','C','E'],['S','F','C','S'],['A','D','E','E']], \\"ABCCED\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[['A','B']], \\"AC\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\\n", "weight": 0.4, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[], \\"A\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\\n", "weight": 0.3, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor direc