9709	13023	\N	\N	#include <iostream>\n#include <string>\n#include <stack>\n#include <cctype>\n\nint main() {\n    std::string s;\n    if (std::getline(std::cin, s)) {\n        std::stack<int> st;\n        int num = 0;\n        char op = '+';\n        for (size_t i = 0; i < s.length(); ++i) {\n            char c = s[i];\n            if (std::isdigit(c)) {\n                num = num * 10 + (c - '0');\n            }\n            if ((!std::isdigit(c) && !std::isspace(c)) || i == s.length() - 1) {\n                if (op == '+') st.push(num);\n                else if (op == '-') st.push(-num);\n                else if (op == '*') {\n                    int top = st.top(); st.pop();\n                    st.push(top * num);\n                } else if (op == '/') {\n                    int top = st.top(); st.pop();\n                    st.push(top / num);\n                }\n                op = c;\n                num = 0;\n            }\n        }\n        int result = 0;\n        while (!st.empty()) {\n            result += st.top();\n            st.pop();\n        }\n        std::cout << result;\n    }\n    return 0;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "3+2*2", "passed": true, "status": "Accepted", "stderr": "", "stdout": "7", "weight": 0.3, "expected": "7", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": " 3/2 ", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": " 3+5 / 2 ", "passed": true, "status": "Accepted", "stderr": "", "stdout": "5", "weight": 0.3, "expected": "5", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Defining main() is strictly forbidden. The system provides its own entry point."}]}}	10.00	2026-07-29 10:24:23.705676+00	t	\N
