10282	14025	\N	\N	#include <iostream>\n#include <algorithm>\n\nclass IntVector {\nprivate:\n    int* data;\n    size_t sz;\n    size_t cap;\npublic:\n    IntVector() : data(nullptr), sz(0), cap(0) {}\n    ~IntVector() { delete[] data; }\n    \n    IntVector(const IntVector& other) : sz(other.sz), cap(other.cap) {\n        data = new int[cap];\n        for (size_t i = 0; i < sz; ++i) data[i] = other.data[i];\n    }\n    \n    IntVector& operator=(const IntVector& other) {\n        if (this != &other) {\n            delete[] data;\n            sz = other.sz;\n            cap = other.cap;\n            data = new int[cap];\n            for (size_t i = 0; i < sz; ++i) data[i] = other.data[i];\n        }\n        return *this;\n    }\n    \n    IntVector(IntVector&& other) noexcept : data(other.data), sz(other.sz), cap(other.cap) {\n        other.data = nullptr;\n        other.sz = 0;\n        other.cap = 0;\n    }\n    \n    IntVector& operator=(IntVector&& other) noexcept {\n        if (this != &other) {\n            delete[] data;\n            data = other.data;\n            sz = other.sz;\n            cap = other.cap;\n            other.data = nullptr;\n            other.sz = 0;\n            other.cap = 0;\n        }\n        return *this;\n    }\n    \n    void push_back(int val) {\n        if (sz == cap) {\n            size_t newCap = cap == 0 ? 1 : cap * 2;\n            int* newData = new int[newCap];\n            for (size_t i = 0; i < sz; ++i) newData[i] = data[i];\n            delete[] data;\n            data = newData;\n            cap = newCap;\n        }\n        data[sz++] = val;\n    }\n    size_t size() const { return sz; }\n};	{"feedback": "Passed 0% of the functional test suites.", "black_box": {"ratio": 0, "test_results": [{"input": "push 1, 2, move assign", "passed": false, "status": "Wrong Answer", "stderr": "", "stdout": "", "weight": 0.3, "expected": "[1, 2]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "copy construct"