10270	14011	\N	\N	#include <vector>\n\nbool hasPath(const std::vector<std::vector<int>>& grid, int r, int c) {\n    int rows = grid.size();\n    if (rows == 0) return false;\n    int cols = grid[0].size();\n    if (r < 0 || r >= rows || c < 0 || c >= cols) return false;\n    if (grid[r][c] == 1) return false;\n    if (r == rows - 1 && c == cols - 1) return true;\n    \n    std::vector<std::vector<bool>> visited(rows, std::vector<bool>(cols, false));\n    auto dfs = [&](auto& self, int cr, int cc) -> bool {\n        if (cr < 0 || cr >= rows || cc < 0 || cc >= cols) return false;\n        if (grid[cr][cc] == 1 || visited[cr][cc]) return false;\n        if (cr == rows - 1 && cc == cols - 1) return true;\n        visited[cr][cc] = true;\n        return self(self, cr + 1, cc) || self(self, cr - 1, cc) ||\n               self(self, cr, cc + 1) || self(self, cr, cc - 1);\n    };\n    return dfs(dfs, r, c);\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[0, 0, 1], [1, 0, 1], [1, 0, 0]], 0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0, 1], [1, 0]], 0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "false\\n", "weight": 0.4, "expected": "false", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[0]], 0, 0", "passed": true, "status": "Accepted", "stderr": "", "stdout": "true\\n", "weight": 0.3, "expected": "true", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 11:50:17.260543+00	t	\N
