9759	13110	\N	\N	#include <vector>\n#include <algorithm>\n\nint maxSubarraySum(const std::vector<int>& nums) {\n    if (nums.empty()) return 0;\n    int maxSoFar = nums[0];\n    int currMax = nums[0];\n    for (size_t i = 1; i < nums.size(); ++i) {\n        currMax = std::max(nums[i], currMax + nums[i]);\n        maxSoFar = std::max(maxSoFar, currMax);\n    }\n    return maxSoFar;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[-2, 1, -3, 4, -1, 2, 1, -5, 4]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "6\\n", "weight": 0.3, "expected": "6", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[-1, -2, -3]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-1\\n", "weight": 0.4, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 10:26:34.085429+00	t	\N
9760	13111	\N	\N	#include <vector>\n\nstd::vector<int> spiralTraversal(const std::vector<std::vector<int>>& matrix) {\n    if (matrix.empty() || matrix[0].empty()) return {};\n    int top = 0, bottom = matrix.size() - 1;\n    int left = 0, right = matrix[0].size() - 1;\n    std::vector<int> result;\n\n    while (top <= bottom && left <= right) {\n        for (int c = left; c <= right; ++c) result.push_back(matrix[top][c]);\n        top++;\n        for (int r = top; r <= bottom; ++r) result.push_back(matrix[r][right]);\n        right--;\n\n        if (top <= bottom) {\n            for (int c = right; c >= left; --c) result.push_back(matrix[bottom][c]);\n            bottom--;\n        }\n        if (left <= right) {\n            for (int r = bottom; r >= top; --r) result.push_back(matrix[r][left]);\n            left++;\n        }\n    }\n    return result;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 2, 3], [4, 5, 6], [7, 8, 9]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[1, 2, 3, 6, 9, 8, 7, 4, 5]\\n", "weight": 0.3, "expected": "[1, 2, 3, 6, 9, 8, 7, 4, 5]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[1]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[1]\\n", "weight": 0.4, "expected": "[1]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[]\\n", "weight": 0.3, "expected": "[]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-29 10:26:37.682122+00	t	\N
