13249	17454	\N	\N	#include <string>\n\nint calculateCompressedLength(const std::string& s) {\n    if (s.empty()) return 0;\n    int compressedLength = 0;\n    int count = 1;\n    for (size_t i = 1; i < s.length(); ++i) {\n        if (s[i] == s[i - 1]) {\n            count++;\n        } else {\n            compressedLength += 1 + std::to_string(count).length();\n            count = 1;\n        }\n    }\n    compressedLength += 1 + std::to_string(count).length();\n    return compressedLength;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "\\"aaabbc\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "6\\n", "weight": 0.3, "expected": "6", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\\"a\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "2\\n", "weight": 0.4, "expected": "2", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "\\"\\"", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-31 10:02:26.587186+00	t	\N
