11018	14785	\N	\N	#include <vector>\n#include <algorithm>\n\nint longestNonDecreasingRun(const std::vector<int>& nums) {\n    if (nums.empty()) return 0;\n    int maxLen = 1;\n    int currLen = 1;\n    for (size_t i = 1; i < nums.size(); ++i) {\n        if (nums[i] >= nums[i - 1]) {\n            currLen++;\n        } else {\n            maxLen = std::max(maxLen, currLen);\n            currLen = 1;\n        }\n    }\n    return std::max(maxLen, currLen);\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 2, 1, 3, 4, 5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "4\\n", "weight": 0.3, "expected": "4", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[5, 4, 3, 2, 1]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "1\\n", "weight": 0.4, "expected": "1", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "0\\n", "weight": 0.3, "expected": "0", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-30 09:10:47.281179+00	t	\N
11019	14786	\N	\N	#include <vector>                                                                      \n                                                                                                     \nstd::vector<int> computeRowAlternatingSums(const std::vector<std::vector<int>>& grid) {\n  std::vector<int> res;                                                              \n  for (size_t r = 0; r < grid.size(); ++r) {                                         \n    int sum = 0;                                                                   \n    for (size_t c = 0; c < grid[r].size(); ++c) {                                  \n      if (c % 2 == 0){\n        sum += grid[r][c];\n      }\n      else {\t\t\t\t\t\t\t\t      \n        sum -= grid[r][c]; \t\t\t\t\t\t      \n      }                                         \t\t\t\t      \n    }                                                                             \n    res.push_back(sum);                                                            \n  }                                                                                  \n  return res;                                                                        \n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 2, 3], [4, 5, 6]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[2, 5]\\n", "weight": 0.5, "expected": "[2, 5]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[10]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[10]\\n", "weight": 0.5, "expected": "[10]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-30 09:10:48.827386+00	t	\N
11020	14787	\N	\N	struct Node {\n    int data;\n    Node* next;\n};\n\nint getMiddleNodeData(Node* head) {\n    if (head == nullptr) return -1;\n    Node* slow = head;\n    Node* fast = head;\n    while (fast != nullptr && fast->next != nullptr) {\n        slow = slow->next;\n        fast = fast->next->next;\n    }\n    return slow->data;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[1, 2, 3, 4, 5]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\\n", "weight": 0.3, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[1, 2, 3, 4]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "3\\n", "weight": 0.4, "expected": "3", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "-1\\n", "weight": 0.3, "expected": "-1", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"name": "Security", "type": "FORBID", "passed": true, "target": "security", "weight": 0, "description": "Security Policy Compliance"}, {"name": "Cyclomatic Complexity", "type": "SCORE", "earned": 30, "passed": true, "target": "complexity", "weight": 30, "description": "Complexity is 4. Penalty applied if > 15.", "actual_value": 4}]}}	10.00	2026-07-30 09:10:50.380002+00	t	\N
