11909	15851	\N	\N	#include <vector>\n\nstd::vector<std::vector<int>> checkBoundaryStatus(const std::vector<std::vector<int>>& grid) {\n    std::vector<std::vector<int>> res = grid;\n    int rows = res.size();\n    if (rows == 0) return res;\n    int cols = res[0].size();\n    for (int r = 0; r < rows; ++r) {\n        for (int c = 0; c < cols; ++c) {\n            bool isBoundary = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);\n            if (!isBoundary) {\n                if (res[r][c] == 5) res[r][c] = -1;\n                else res[r][c] = -2;\n            }\n        }\n    }\n    return res;\n}	{"feedback": "Passed 100% of the functional test suites.", "black_box": {"ratio": 1, "test_results": [{"input": "[[1, 2, 3], [4, 5, 6], [7, 8, 9]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[1, 2, 3], [4, -1, 6], [7, 8, 9]]\\n", "weight": 0.3, "expected": "[[1, 2, 3], [4, -1, 6], [7, 8, 9]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[1, 1], [1, 1]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[1, 1], [1, 1]]\\n", "weight": 0.4, "expected": "[[1, 1], [1, 1]]", "is_public": true, "memory_leak": false, "compile_output": ""}, {"input": "[[5, 5, 5], [5, -3, 5], [5, 5, 5]]", "passed": true, "status": "Accepted", "stderr": "", "stdout": "[[5, 5, 5], [5, -2, 5], [5, 5, 5]]\\n", "weight": 0.3, "expected": "[[5, 5, 5], [5, -2, 5], [5, 5, 5]]", "is_public": true, "memory_leak": false, "compile_output": ""}]}, "white_box": {"ratio": 1, "details": [{"passed": false, "description": "Preprocessor directives (#include, #define) are not allowed. Necessary headers are included by the judge."}]}}	10.00	2026-07-31 06:46:24.993942+00	t	\N
